def gen(rng):
    def fmt(n, edges):
        edges = list(edges)
        rng.shuffle(edges)
        edges = [(a, b) if rng.random() < 0.5 else (b, a) for a, b in edges]
        return f"{n} {len(edges)}" + ''.join(f'\n{a} {b}' for a, b in edges)
    def relabel(n, edges):
        perm = list(range(n))
        rng.shuffle(perm)
        return [(perm[a], perm[b]) for a, b in edges]
    def rand_connected(n, extra):
        es = set()
        for i in range(1, n):
            es.add((rng.randrange(i), i))
        tries = 0
        while extra > 0 and tries < 10 * extra + 10:
            tries += 1
            a, b = rng.randrange(n), rng.randrange(n)
            if a == b:
                continue
            a, b = min(a, b), max(a, b)
            if (a, b) not in es:
                es.add((a, b))
                extra -= 1
        return sorted(es)
    def blocks(sizes):
        # chain/tree of cliques/cycles sharing single vertices
        es = set()
        n = 1
        for s in sizes:
            attach = rng.randrange(n)
            verts = [attach] + list(range(n, n + s - 1))
            n += s - 1
            if s == 2:
                es.add((min(verts), max(verts)))
            elif rng.random() < 0.5:
                for i in range(s):
                    a, b = verts[i], verts[(i + 1) % s]
                    es.add((min(a, b), max(a, b)))
            else:
                for i in range(s):
                    for j in range(i + 1, s):
                        a, b = verts[i], verts[j]
                        es.add((min(a, b), max(a, b)))
        return n, sorted(es)
    tests = [fmt(1, []), fmt(2, [(0, 1)]), fmt(3, [(0, 1), (1, 2)]), fmt(3, [(0, 1), (1, 2), (0, 2)]),
             fmt(5, [(0, i) for i in range(1, 5)]), fmt(4, [(0, 1), (1, 2), (2, 3), (3, 0)]),
             fmt(7, [(0, 1), (1, 2), (2, 0), (2, 3), (3, 4), (4, 5), (5, 3), (5, 6)])]
    for n in (4, 5, 6, 8, 10, 12, 16, 20):
        for extra in (0, n // 3, n):
            tests.append(fmt(n, relabel(n, rand_connected(n, extra))))
    for _ in range(6):
        sizes = [rng.randint(2, 4) for _ in range(rng.randint(2, 6))]
        n, es = blocks(sizes)
        tests.append(fmt(n, relabel(n, es)))
    n = 5000
    tests.append(fmt(n, relabel(n, [(i, i + 1) for i in range(n - 1)])))
    tests.append(fmt(n, relabel(n, rand_connected(n, 0))))
    tests.append(fmt(n, relabel(n, rand_connected(n, 300))))
    tests.append(fmt(n, relabel(n, rand_connected(n, 15000))))
    sizes = [rng.randint(2, 5) for _ in range(1500)]
    nn, es = blocks(sizes)
    tests.append(fmt(nn, relabel(nn, es)))
    n2 = 5000
    es = [(i, (i + 1) % n2) for i in range(n2)]
    tests.append(fmt(n2, relabel(n2, es)))
    return tests
